 point(source,p){return p?source.object3D.parent.localToWorld(new T.Vector3(p.x,p.y,p.z)):source.object3D.getWorldPosition(new T.Vector3())},
 start(source,p,target){if(this.source||!source||!visible(this.el))return false;if(!this.pose)this.home={position:this.el.object3D.position.clone(),quaternion:this.el.object3D.quaternion.clone(),scale:this.el.object3D.scale.clone()};this.source=source;window.GlobiquestPanelInput?.reserve(source);this.target=target;this.startPoint=this.point(source,p);this.startPosition=this.el.object3D.getWorldPosition(new T.Vector3());this.moved=false;const camera=window.globiquest.xrHeadPose?.()?.position||this.el.sceneEl.camera.getWorldPosition(new T.Vector3()),near=this.startPoint.distanceTo(this.startPosition)<.3;this.gain=near?1:T.MathUtils.clamp(camera.distanceTo(this.startPosition)/Math.max(.35,camera.distanceTo(this.startPoint)),1,this.el.id==='nav'?3:1.8);this.navRayStart=null;if(this.el.id==='nav'&&!near){const ray=window.globiquest.handRay?.(source,p)||document.getElementById('earthRoot')?.components['globe-rotation']?.controllerRay?.(source);if(ray){this.navRayDistance=ray.origin.distanceTo(this.startPosition);this.navRayStart=ray.origin.clone().addScaledVector(ray.direction,this.navRayDistance)}}return true},
 move(source,p){if(this.source!==source||this.mouse)return;let delta=this.point(source,p).sub(this.startPoint).multiplyScalar(this.gain||1);if(this.navRayStart){const ray=window.globiquest.handRay?.(source,p)||document.getElementById('earthRoot')?.components['globe-rotation']?.controllerRay?.(source);if(ray)delta=ray.origin.clone().addScaledVector(ray.direction,this.navRayDistance).sub(this.navRayStart)}if(delta.length()>.012)this.moved=true;if(this.moved)this.place(this.startPosition.clone().add(delta))},
 place(world){const camera=window.globiquest.xrHeadPose?.()?.position||this.el.sceneEl.camera.getWorldPosition(new T.Vector3()),offset=world.clone().sub(camera),minimum=window.globiquest.controlInput==='tap'&&this.el.id!=='nav'?.45:1.1;if(offset.length()<minimum)world.copy(camera).add(offset.lengthSq()?offset.normalize().multiplyScalar(minimum):new T.Vector3(0,0,-minimum));const object=this.el.object3D;object.position.copy(object.parent.worldToLocal(world));object.lookAt(camera);object.updateWorldMatrix(true,true);this.pose={position:object.getWorldPosition(new T.Vector3()),quaternion:object.getWorldQuaternion(new T.Quaternion()),scale:object.getWorldScale(new T.Vector3())};this.el.setAttribute('position',{x:object.position.x,y:object.position.y,z:object.position.z});this.el.setAttribute('rotation',{x:T.MathUtils.radToDeg(object.rotation.x),y:T.MathUtils.radToDeg(object.rotation.y),z:T.MathUtils.radToDeg(object.rotation.z)});this.el.dataset.panelManual='true';if(this.el.id==='nav'&&this.el.sceneEl.components?.['xr-view'])this.el.sceneEl.components['xr-view'].navManual=true;this.syncHandle()},
 restorePose(){if(!this.pose||this.source)return;const object=this.el.object3D,parent=object.parent;object.position.copy(parent.worldToLocal(this.pose.position.clone()));object.quaternion.copy(parent.getWorldQuaternion(new T.Quaternion()).invert().multiply(this.pose.quaternion));object.scale.copy(this.pose.scale).divide(parent.getWorldScale(new T.Vector3()));object.updateWorldMatrix(true,true)},
 startMouse(ray,target){if(this.source)return false;if(!this.pose)this.home={position:this.el.object3D.position.clone(),quaternion:this.el.object3D.quaternion.clone(),scale:this.el.object3D.scale.clone()};this.source='mouse';this.mouse=true;this.target=target;this.moved=false;this.startPosition=this.el.object3D.getWorldPosition(new T.Vector3());this.plane=new T.Plane().setFromNormalAndCoplanarPoint(this.el.sceneEl.camera.getWorldDirection(new T.Vector3()),this.startPosition);this.startPoint=ray.intersectPlane(this.plane,new T.Vector3());if(!this.startPoint){this.source=null;this.mouse=false}return !!this.startPoint},
 moveMouse(ray){if(!this.mouse)return;const point=ray.intersectPlane(this.plane,new T.Vector3());if(point&&point.distanceTo(this.startPoint)>.012){this.moved=true;this.place(this.startPosition.clone().add(point.sub(this.startPoint)))}},
 end(cancel=false){const tapped=this.source&&!this.moved&&!cancel&&this.target?.getAttribute?.('data-drag-only')!=='true';window.GlobiquestPanelInput?.release(this.source);this.source=null;this.target=null;this.navRayStart=null;this.mouse=false;if(tapped)this.toggleMoveControls()},
 syncHandle(){if(!this.gripLocal)return;const object=this.el.object3D;object.updateWorldMatrix(true,false);const world=object.localToWorld(this.gripLocal.clone()),parent=this.handle.object3D.parent;this.handle.object3D.position.copy(parent.worldToLocal(world));this.handle.object3D.quaternion.copy(parent.getWorldQuaternion(new T.Quaternion()).invert().multiply(object.getWorldQuaternion(new T.Quaternion())));this.handle.object3D.updateWorldMatrix(true,true);const close=this.closeHandle.object3D;close.position.copy(this.handle.object3D.position).add(new T.Vector3(.23,0,0).applyQuaternion(this.handle.object3D.quaternion));close.quaternion.copy(this.handle.object3D.quaternion);close.updateWorldMatrix(true,true);if(this.positionHandle){this.positionHandle.object3D.position.copy(this.handle.object3D.position).add(new T.Vector3(.05,this.zoomHandle?.21:.105,0).applyQuaternion(this.handle.object3D.quaternion));this.positionHandle.object3D.quaternion.copy(this.handle.object3D.quaternion);this.positionHandle.object3D.updateWorldMatrix(true,true)}if(this.zoomHandle){this.zoomHandle.object3D.position.copy(this.handle.object3D.position).add(new T.Vector3(.05,.105,0).applyQuaternion(this.handle.object3D.quaternion));this.zoomHandle.object3D.quaternion.copy(this.handle.object3D.quaternion);this.zoomHandle.object3D.updateWorldMatrix(true,true)}},
 header(){const object=this.el.object3D;object.updateWorldMatrix(true,true);const inverse=object.matrixWorld.clone().invert(),bounds=new T.Box3(),box=new T.Box3();object.traverse(o=>{if(!o.isMesh)return;for(let p=o;p&&p!==object;p=p.parent)if(!p.visible||p.userData.panelGrip)return;if(!o.geometry.boundingBox)o.geometry.computeBoundingBox();box.copy(o.geometry.boundingBox).applyMatrix4(inverse.clone().multiply(o.matrixWorld));bounds.union(box)});if(bounds.isEmpty()){this.gripLocal=null;return}const scale=object.getWorldScale(new T.Vector3()).x,width=Math.min(.24,(bounds.max.x-bounds.min.x)*scale*.8);this.handle.setAttribute('width',width);this.handle.setAttribute('height',.085);this.gripLocal=new T.Vector3((bounds.min.x+bounds.max.x)/2,bounds.max.y+(.014+.085/2)/scale,.0004);this.syncHandle()},
 tick(time){if(!visible(this.el)){this.end(true)}else{if(this.source&&!this.mouse&&['leftHand','rightHand'].includes(this.source.id))this.move(this.source);if(!this.source)this.restorePose()}for(const control of [this.handle,this.closeHandle,this.zoomHandle,this.positionHandle])control?.setAttribute('visible',false)},
